function RoleSelection() { const navigate=useNavigate(); return <div className="min-h-screen bg-[#9C0000] px-5 py-8 text-white"><div className="absolute inset-0 paisley-bg opacity-30"/><header className="relative mx-auto flex max-w-6xl items-center justify-between"><Logo light/><LanguageSelector/></header><main className="relative mx-auto max-w-5xl py-20 text-center"><div className="mx-auto mb-5 flex h-14 w-14 items-center justify-center rounded-full border border-[#D4AF37] bg-[#D4AF37]/15 text-[#FFE7A6]"><Crown size={25}/></div><p className="text-xs font-bold uppercase tracking-[.28em] text-[#E8C754]">KalaSetu AI</p><h1 className="mt-4 font-serif text-5xl text-[#FFF5D6] md:text-7xl">Welcome to KalaSetu AI</h1><p className="mt-5 text-lg text-[#F4D1C3]">Choose how you want to continue</p><div className="mx-auto mt-14 grid max-w-3xl gap-5 text-left md:grid-cols-2"><button onClick={()=>navigate("/login")} className="group rounded-3xl border border-[#D4AF37]/60 bg-[#7B0000]/70 p-7 transition hover:-translate-y-2 hover:bg-[#860000]"><span className="text-5xl">👩‍🎨</span><h2 className="mt-7 font-serif text-3xl text-[#FFE7A6]">SELLER / ARTISAN</h2><p className="mt-3 leading-6 text-[#F5D6C8]">Showcase, manage and sell your craftsmanship</p><span className="mt-8 inline-flex items-center text-sm font-semibold text-[#E8C754]">Enter seller studio <ArrowRight className="ml-2" size={17}/></span></button><button onClick={()=>navigate("/buyer/login")} className="group rounded-3xl border border-[#D4AF37]/60 bg-[#FFF2C9] p-7 text-[#3A120C] transition hover:-translate-y-2 hover:bg-[#FFE7A6]"><span className="text-5xl">🛍️</span><h2 className="mt-7 font-serif text-3xl text-[#9C0000]">BUYER</h2><p className="mt-3 leading-6 text-[#765A4E]">Discover authentic Indian crafts</p><span className="mt-8 inline-flex items-center text-sm font-semibold text-[#9C0000]">Explore the collection <ArrowRight className="ml-2" size={17}/></span></button></div></main></div>; }
